import{describe,it,expect,beforeEach,vi}from"vitest";import{I18nEngine,SUPPORTED_LANGUAGES,DEFAULT_LANGUAGE}from"../../js-modules/i18n-engine.js";function makeEngine(e={}){return new I18nEngine({loadDictionary:async t=>e[t]||{}})}describe("I18nEngine",()=>{beforeEach(()=>{localStorage.clear()}),it("defaults to English when nothing is persisted and locale is unsupported",()=>{const e=makeEngine();expect(e.getCurrentLanguage()).toBe(DEFAULT_LANGUAGE)}),it("exposes every supported language with a native label",()=>{const e=makeEngine().getLanguages().map(e=>e.code);expect(e).toContain("hi"),expect(e).toContain("ta"),expect(SUPPORTED_LANGUAGES.find(e=>"hi"===e.code).nativeLabel).toBe("हिन्दी")}),it("falls back to English when a key is missing in the active language",async()=>{const e=makeEngine({en:{nav:{home:"Home"}},hi:{}});await e.setLanguage("hi"),expect(e.translate("nav.home")).toBe("Home"),expect(e.getStatus("nav.home","hi")).toBe("missing")}),it("prefers the active language dictionary over the English fallback",async()=>{const e=makeEngine({en:{nav:{home:"Home"}},hi:{nav:{home:"होम"}}});await e.setLanguage("hi"),expect(e.translate("nav.home")).toBe("होम")}),it("returns the key itself when no translation and no fallback exist anywhere",async()=>{const e=makeEngine({en:{}});expect(e.translate("does.not.exist")).toBe("does.not.exist")}),it("interpolates {{vars}} into the resolved string",async()=>{const e=makeEngine({en:{greeting:"Hello, {{name}}!"}});await e.setLanguage("en"),expect(e.translate("greeting",{vars:{name:"Asha"}})).toBe("Hello, Asha!")}),it("layers AI translations below human overrides",async()=>{const e=makeEngine({en:{title:"Title"},hi:{}});await e.setLanguage("hi"),e.setAiTranslation("hi","title","शीर्षक (AI)"),expect(e.translate("title")).toBe("शीर्षक (AI)"),expect(e.getStatus("title")).toBe("ai"),e.setOverride("hi","title","शीर्षक"),expect(e.translate("title")).toBe("शीर्षक"),expect(e.getStatus("title")).toBe("human")}),it("persists the selected language across engine instances via localStorage",async()=>{const e=makeEngine({hi:{}});await e.setLanguage("hi");const t=makeEngine({hi:{}});expect(t.getCurrentLanguage()).toBe("hi")}),it("persists manual overrides across engine instances (simulating dashboard edits)",async()=>{const e=makeEngine({en:{nav:{home:"Home"}},hi:{}});await e.setLanguage("hi"),e.setOverride("hi","nav.home","होम (सही किया गया)");const t=makeEngine({en:{nav:{home:"Home"}},hi:{}});await t.setLanguage("hi"),expect(t.translate("nav.home")).toBe("होम (सही किया गया)"),expect(t.getStatus("nav.home")).toBe("human")}),it("notifies listeners and dispatches a window event on language change",async()=>{const e=makeEngine({hi:{}}),t=vi.fn();e.on("languagechange",t);const n=vi.fn();window.addEventListener("i18n:languagechange",n),await e.setLanguage("hi"),expect(t).toHaveBeenCalledWith({language:"hi"}),expect(n).toHaveBeenCalledTimes(1)}),it("applyToDOM translates [data-i18n] elements within a subtree",async()=>{document.body.innerHTML='\n      <div id="scope">\n        <h1 data-i18n="nav.home"></h1>\n        <input data-i18n-placeholder="common.searchPlaceholder" />\n      </div>\n    ';const e=makeEngine({en:{nav:{home:"Home"},common:{searchPlaceholder:"Search..."}}});await e.setLanguage("en"),e.applyToDOM(document.getElementById("scope")),expect(document.querySelector("h1").textContent).toBe("Home"),expect(document.querySelector("input").getAttribute("placeholder")).toBe("Search...")}),it("supports single-brace {var} interpolation alongside {{var}}",async()=>{const e=makeEngine({en:{welcome:"Welcome, {userName} to {{siteName}}!"}});await e.setLanguage("en");const t=e.translate("welcome",{vars:{userName:"Rishab",siteName:"India Explorer"}});expect(t).toBe("Welcome, Rishab to India Explorer!")}),it("applyToDOM updates data-i18n-attr and document.documentElement lang attribute",async()=>{document.body.innerHTML='\n      <div id="scope">\n        <button data-i18n-attr="title:nav.homeTitle,aria-label:nav.homeAria"></button>\n      </div>\n    ';const e=makeEngine({en:{nav:{homeTitle:"Go Home",homeAria:"Home Button"}}});await e.setLanguage("en"),e.applyToDOM(document.getElementById("scope"));const t=document.querySelector("button");expect(t.getAttribute("title")).toBe("Go Home"),expect(t.getAttribute("aria-label")).toBe("Home Button"),expect(document.documentElement.getAttribute("lang")).toBe("en")})});